<script lang="ts">import{onMount}from'svelte';import'../../../fullstack-shared/style.css';let{data}=$props();let label=$state(''),status=$state(''),busy=$state(false),hydrated=$state(false);onMount(()=>{hydrated=true;});async function probe(save=false){busy=true;try{const response=await fetch('/sveltekit/api/verification',{method:save?'POST':'GET',...(save?{headers:{'Content-Type':'application/json'},body:JSON.stringify({label})}:{})});const value=await response.json();if(!response.ok)throw Error(value.error);label=value.label;status=save?'已保存到 KV':'读取成功 · '+value.framework;}catch(e){status=e.message;}finally{busy=false;}}</script>
<svelte:head><title>WorkerKit · SvelteKit</title></svelte:head><header><strong>WorkerKit · SvelteKit</strong><a href="/">方案选择</a></header><main><h1>SvelteKit 全栈验证</h1><p class="muted">真正的服务端渲染、SvelteKit API 路由、Better Auth 会话与 Cloudflare KV。</p><div class="grid"><section><h2>服务端渲染</h2><p>框架：SvelteKit 3</p><p>服务端生成时间：<code data-ssr-time>{data.renderedAt}</code></p><p>当前身份：{data.user||'未登录'}</p><a href="/standard/?redirect=%2Fsveltekit%2F">登录 Hono + Better Auth</a></section><section><h2>原生 API 与 KV</h2><form onsubmit={event=>{event.preventDefault();probe(true);}}><label for="label">验证名称</label><input id="label" bind:value={label} maxlength="80" disabled={!hydrated}/><nav><button type="button" disabled={busy||!hydrated} onclick={()=>probe()}>读取 KV</button><button type="submit" disabled={busy||!hydrated}>保存 KV</button></nav></form><p role="status">{status}</p></section></div><section><h2>开发业务</h2><p>这个示例验证全栈部署链路。用户、任务、密钥、审计和 API 中心可以复用统一业务后端。</p><nav><a class="button" href="/standard/">打开管理工作台</a><a href="/docs/frameworks.html">查看接入说明</a><a href="/sveltekit/api/verification">查看原生 API</a></nav></section></main>
